// 공유 스냅샷 페이지 (읽기 전용)
import { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { getSnapshotByToken } from '../stores/workFirestore';
import type { Snapshot, ProjectTodo } from '../types/work';
import '../styles/SharePage.css';

export default function SharePage() {
  const { token } = useParams<{ token: string }>();
  const [snapshot, setSnapshot] = useState<Snapshot | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function loadSnapshot() {
      if (!token) {
        setError('유효하지 않은 링크입니다.');
        setIsLoading(false);
        return;
      }

      try {
        const snap = await getSnapshotByToken(token);
        if (snap) {
          setSnapshot(snap);
        } else {
          setError('스냅샷을 찾을 수 없습니다.');
        }
      } catch (err) {
        console.error('Failed to load snapshot:', err);
        setError('스냅샷을 불러오는 중 오류가 발생했습니다.');
      } finally {
        setIsLoading(false);
      }
    }

    loadSnapshot();
  }, [token]);

  if (isLoading) {
    return (
      <div className="share-page">
        <div className="share-loading">
          <div className="loading-spinner"></div>
          <p>스냅샷을 불러오는 중...</p>
        </div>
      </div>
    );
  }

  if (error || !snapshot) {
    return (
      <div className="share-page">
        <div className="share-error">
          <div className="error-icon">⚠️</div>
          <h2>오류</h2>
          <p>{error || '스냅샷을 찾을 수 없습니다.'}</p>
          <Link to="/" className="home-link">홈으로 돌아가기</Link>
        </div>
      </div>
    );
  }

  const { project, tasks, todos, created_at } = snapshot;

  // 날짜 포맷
  const formatDate = (dateStr: string | null): string => {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ko-KR', { month: 'short', day: 'numeric' });
  };

  // 태스크별 투두 그룹핑
  const todosByTask = todos.reduce((acc, todo) => {
    const taskId = todo.taskId || 'unassigned';
    if (!acc[taskId]) acc[taskId] = [];
    acc[taskId].push(todo);
    return acc;
  }, {} as Record<string, ProjectTodo[]>);

  return (
    <div className="share-page">
      {/* 헤더 */}
      <header className="share-header">
        <div className="share-badge">📤 공유된 프로젝트</div>
        <div className="share-meta">
          스냅샷 생성: {new Date(created_at).toLocaleDateString('ko-KR', {
            year: 'numeric',
            month: 'long',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
          })}
        </div>
      </header>

      {/* 프로젝트 정보 */}
      <section className="project-section">
        <div className="project-header">
          <span 
            className="project-color" 
            style={{ backgroundColor: project.color }}
          />
          <h1 className="project-title">{project.title}</h1>
        </div>
        {(project.start_at || project.end_at || project.due_at) && (
          <div className="project-dates">
            {project.start_at && (
              <span>시작: {formatDate(project.start_at)}</span>
            )}
            {project.end_at && (
              <span>종료: {formatDate(project.end_at)}</span>
            )}
            {project.due_at && (
              <span>마감: {formatDate(project.due_at)}</span>
            )}
          </div>
        )}
      </section>

      {/* 태스크 목록 */}
      <section className="tasks-section">
        <h2 className="section-title">
          📋 태스크 ({tasks.length})
        </h2>
        
        {tasks.length === 0 ? (
          <div className="empty-message">태스크가 없습니다.</div>
        ) : (
          <ul className="task-list">
            {tasks.map((task) => (
              <li key={task.id} className={`task-item ${task.status === 'DONE' ? 'done' : ''}`}>
                <div className="task-header">
                  <span className={`task-status ${task.status === 'DONE' ? 'done' : ''}`}>
                    {task.status === 'DONE' ? '✓' : '○'}
                  </span>
                  <span className="task-title">{task.title}</span>
                </div>
                
                {(task.start_at || task.due_at) && (
                  <div className="task-dates">
                    {task.start_at && formatDate(task.start_at)}
                    {task.start_at && task.due_at && ' → '}
                    {task.due_at && `마감 ${formatDate(task.due_at)}`}
                  </div>
                )}
                
                {/* 태스크 하위 투두 */}
                {todosByTask[task.id] && todosByTask[task.id].length > 0 && (
                  <ul className="todo-list">
                    {todosByTask[task.id].map((todo) => (
                      <li key={todo.id} className={`todo-item ${todo.is_done ? 'done' : ''}`}>
                        <span className={`todo-status ${todo.is_done ? 'done' : ''}`}>
                          {todo.is_done ? '✓' : '○'}
                        </span>
                        <span className="todo-content">{todo.content}</span>
                      </li>
                    ))}
                  </ul>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>

      {/* 미할당 투두 */}
      {todosByTask['unassigned'] && todosByTask['unassigned'].length > 0 && (
        <section className="unassigned-section">
          <h2 className="section-title">
            📝 기타 투두 ({todosByTask['unassigned'].length})
          </h2>
          <ul className="todo-list standalone">
            {todosByTask['unassigned'].map((todo) => (
              <li key={todo.id} className={`todo-item ${todo.is_done ? 'done' : ''}`}>
                <span className={`todo-status ${todo.is_done ? 'done' : ''}`}>
                  {todo.is_done ? '✓' : '○'}
                </span>
                <span className="todo-content">{todo.content}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* 푸터 */}
      <footer className="share-footer">
        <p>Myschedul로 생성된 공유 스냅샷입니다.</p>
      </footer>
    </div>
  );
}
